\label{def:functions}
The circle coordinate $C$ and the normal coordinate $N$ are the
holomorphic germs at $z_*$ defined along $J$ by
\begin{equation}\label{eq:functions}
 C=e^{i\ell},\qquad N=e^{i\beta}.
\end{equation}

\label{prop:continuation}
The germs $C$ and $N$ extend to nonconstant meromorphic functions
on $\widetilde{\mathcal S_4}$. With suitable orientations of
the two circle coordinates, they satisfy
\begin{equation}\label{eq:differential-relation}
 \mathrm{d}\log C\,\mathrm{d}\log N
 =2iQ=2iq_*\frac{\mathrm{d} z^2}{p(z)}
\end{equation}
as meromorphic quadratic differentials, where $Q$ is the Hopf
differential in~\eqref{eq:hopf}, and
\begin{equation}\label{eq:scalar-reflection}
 C^\#=C^{-1},\qquad N^\#=N^{-1}.
\end{equation}
For each $j$, analytic continuation along $\gamma_j^{n_j}$ returns
every branch of $(C,N)$ to its initial germs. Here $n_j$ is defined in~\eqref{eq:quotient-local-degrees}, and
$\gamma_j^{n_j}$ denotes the loop $\gamma_j$ repeated $n_j$ times.

\label{lem:vertex}
There is a conformal coordinate $w$ centered at $x_1$, real along
$E$, in which the initial branches of $C$ and $N$ extend
holomorphically, with $C(0)N(0)\ne0$, and
\begin{equation}\label{eq:vertex}
 z-p_1=\kappa_0 w^{n_1}+O(w^{n_1+1}),\qquad
 C-C(0)=\kappa_1w+O(w^2),
\end{equation}
for some $\kappa_0,\kappa_1\in\mathbb{C}\setminus\{0\}$. Moreover,
\[
 \operatorname{ord}_{w=0}(\mathrm{d}\log N)=n_1-2.
\]

\label{def:finite-monodromy}
We say the pair $(C,N)$ has \emph{finite monodromy} if the set of germs
\[
 \bigl\{(C^\gamma,N^\gamma):\gamma\in\pi_1(\mathcal S_4,z_*)\bigr\}
\]
at $z_*$ is finite.

\label{prop:reflection}
If $\gamma\in\pi_1(\mathcal S_4,z_*)$ has trivial monodromy on both $C$ and $N$,
that is,
\[
 C^\gamma=C,\qquad N^\gamma=N,
\]
then
\begin{equation}\label{eq:reflection-monodromy}
 M_\gamma=M_{\delta\gamma}
\end{equation}
as holomorphic $\operatorname{SL}(2,\mathbb{C})$-valued functions of $\lambda\in\mathbb{C}^*$.

\label{prop:infinite-monodromy}
For $k\geq l\geq1$ with $kl>1$, the pair $(C,N)$ associated with the Lawson surface
$\xi_{k,l}$ does not have finite monodromy on $\mathcal S_4$.
